#!/usr/bin/env node
// Regenerates js/connector-src.js from connector/Tesla-Grid-Player-Connector.user.js (so the page can offer
// Download / Copy buttons even when opened from file://, where it can't fetch neighbouring files).
const fs = require("fs"), path = require("path");
const root = path.join(__dirname, "..");
const src = fs.readFileSync(path.join(root, "connector", "Tesla-Grid-Player-Connector.user.js"), "utf8");
fs.writeFileSync(path.join(root, "js", "connector-src.js"),
  "/* connector-src.js — GENERATED by tools/embed-connector.js from connector/Tesla-Grid-Player-Connector.user.js. Do not edit. */\n" +
  "window.TDC = window.TDC || {};\nwindow.TDC.CONNECTOR_FILENAME = \"Tesla-Grid-Player-Connector.user.js\";\nwindow.TDC.CONNECTOR_SRC = " + JSON.stringify(src) + ";\n");
console.log("wrote js/connector-src.js (" + src.length + " chars)");
